class Solution:
    def isValid(self, s):
        """
        :type s: str
        :rtype: bool
        """
        mapping = {"}": "{", ")": "(", "]": "["}
        stack = []
        for char in s:
            # print('Каждый запрос', stack)
            if char in mapping.values():
                stack.append(char)

            elif char in mapping:
                if not stack:
                    return False
                top = stack.pop()
                if top != mapping[char]:
                    return False
            else:
                return False
        return len(stack) == 0


